package main

import (
	"database/sql"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int
	Name  string
	Price float64
	Desc  string
}

// searchHandler allows users to search products by category and keyword
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	keyword := r.URL.Query().Get("q")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		category = "all"
	}
	if sortBy == "" {
		sortBy = "name"
	}

	// Build query with filters
	var queryBuilder strings.Builder
	queryBuilder.WriteString("SELECT id, name, price, description FROM products WHERE 1=1")

	if category != "all" {
		// Category is validated against known list
		validCategories := map[string]bool{"electronics": true, "books": true, "clothing": true, "home": true}
		if !validCategories[category] {
			http.Error(w, "Invalid category", http.StatusBadRequest)
			return
		}
		queryBuilder.WriteString(fmt.Sprintf(" AND category = '%s'", category))
	}

	if keyword != "" {
		// Direct string interpolation - VULNERABLE to SQL injection
		queryBuilder.WriteString(fmt.Sprintf(" AND (name ILIKE '%%%s%%' OR description ILIKE '%%%s%%')", keyword, keyword))
	}

	// Sort validation looks safe but sortBy is used directly
	allowedSorts := []string{"name", "price", "id"}
	sortValid := false
	for _, s := range allowedSorts {
		if s == sortBy {
			sortValid = true
			break
		}
	}
	if !sortValid {
		sortBy = "name"
	}
	queryBuilder.WriteString(fmt.Sprintf(" ORDER BY %s LIMIT 50", sortBy))

	query := queryBuilder.String()
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}

	tmpl := template.Must(template.ParseFiles("templates/search.html"))
	tmpl.Execute(w, products)
}

// detailHandler shows product details - uses parameterized query
func detailHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	err := db.QueryRow("SELECT id, name, price, description FROM products WHERE id = $1", id).Scan(&p.ID, &p.Name, &p.Price, &p.Desc)
	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	tmpl := template.Must(template.ParseFiles("templates/detail.html"))
	tmpl.Execute(w, p)
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/product", detailHandler)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})
	log.Fatal(http.ListenAndServe(":8080", nil))
}
